			if(Fuell[vehicleid] >=180) return SendClientMessage(playerid, COLOR_RED, "[Ошибка] > Бак транспорта ещё полон!");
			SendClientMessage(playerid, COLOR_GREEN, "[Успешно] > Вы заправили транспорт 20 литрами бензина");
			Fuell[vehicleid] += 20;
			PlayerInfo[playerid][pIFuel] = 0;
